mapper.select:
SELECT a.asgn_id, a.dev_id, d.dev_nm, coalesce(c.emp_se_cd,d.emp_se_cd) AS emp_se_cd,
       a.prj_id, p.prj_nm, a.end_dt
FROM asgn.asgn a
JOIN mst.dev d ON d.dev_id=a.dev_id
JOIN prj.prj p ON p.prj_id=a.prj_id
LEFT JOIN cst.mth_cst c ON c.dev_id=a.dev_id AND c.cst_ym=#{month}
WHERE p.prj_stts_cd='RUN' AND p.cntrct_ty_cd IN ('MO','DP')
  AND a.asgn_stts_cd='ACTIVE' AND a.asgn_se_cd!='FREE'
  AND a.bgn_dt <=#{today} AND a.end_dt >=#{today} AND a.end_dt <=#{throughDate}
  AND coalesce(c.emp_se_cd,d.emp_se_cd)=#{empType}
  AND a.prj_id=#{projectId}
ORDER BY a.asgn_id
